import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { EmisService } from 'src/app/services/emis/emis.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import { DomSanitizer } from '@angular/platform-browser';

@Component({
  selector: 'app-arp-course-materials',
  templateUrl: './arp-course-materials.page.html',
  styleUrls: ['./arp-course-materials.page.scss'],
})
export class ArpCourseMaterialsPage implements OnInit {
  emisName: any;
  day: number;
  week: number;
  curr_month: number;
  data: any;
  vidUrl: any;
  filename: any;
  downloadedname: string;

  constructor(public router:Router,private userSessionService: UserSessionService,private emisService: EmisService,
    private domsaintizer: DomSanitizer) {
    this.emisName = this.userSessionService.emis_username()
    let currentDate = new Date();
    this.day = currentDate.getDay()
    var date = currentDate.getDate();
    this.curr_month = currentDate.getMonth() +1;
    // var weekOfMonth = Math.ceil((date - 1 - this.day) / 7);
    var weekOfMonth = (0 | currentDate.getDate() / 7)+1;
    this.week = weekOfMonth
   }

  ngOnInit() {
    let data = {
      "ArpId": this.emisName,
      "Mont": this.curr_month,
      "Week": this.week,
      "Type": 2
    }
    this.data = [];
    this.emisService.ArpCourMat(data).subscribe(res => {
      if(res.dataStatus){
        this.data = res.result;
        this.downloadedname = this.data[0].video_1
        this.playVideo()
      }
    });
  }
  ionViewDidEnter() {
      this.inital()
  }
  inital() {
    let data = {
      "ArpId": this.emisName,
      "Mont": this.curr_month,
      "Week": this.week,
      "Type": 2
    }
    this.data = [];
    this.emisService.ArpCourMat(data).subscribe(res => {
      if(res.dataStatus){
        this.data = res.result;
        this.downloadedname = this.data[0].video_1
        this.playVideo()
      }
    });
  }

  playVideo() {
    this.destroyVideo() 
    this.filename = '';
    var A = Date.now();
    this.filename = A;
    // this.downloadedname = 'f0cefeb1b4bc4d92ab313b7acdd35d68'
    let videoUrl = this.domsaintizer.bypassSecurityTrustResourceUrl("https://d1p3r7kc5uix85.cloudfront.net/" + this.downloadedname);
    this.vidUrl = videoUrl
  }

  destroyVideo() {
    let videoElement=  <HTMLVideoElement>document.getElementById(this.filename);
    videoElement.pause();
    this.vidUrl=""
    videoElement.src="";
    videoElement.removeAttribute('src');
    videoElement.load();
  }

  backBtn(){
    this.router.navigate(["/tabs/art-culture"])
  }

}
